@dataclass
class Matter:
    ref: str
    client: str
    settlement: str
    status: str

def label(m: Matter) -> str:
    return f"{m.ref} {m.client}"

#!/bin/bash
set -uo pipefail
[ $# -gt 0 ] || { echo "usage: $0 file..." >&2; exit 2; }
for f in "$@"; do
  wc -l "$f"
done

func label(s Status) string {
	switch s {
	case Open:
		return "open"
	case Settled:
		return "settled"
	}
	return "unknown"
}

